$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$groupActions = Decode ""
$actionsRoute = Decode ""

$helperPath = Join-Path $root "lib\brain-group-cancellation-actions.ts"
$routePath = Join-Path $root "app\api\brain\actions\route.ts"
$brainPath = Join-Path $root "lib\brain-actions.ts"

foreach ($path in @($routePath, $brainPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "12.91 : fichier requis introuvable : $path"
    }
}

$brain = [System.IO.File]::ReadAllText($brainPath)

if (-not $brain.Contains("KLYX_SERVER_BRAIN_ACTIONS_12_81")) {
    throw "12.91 : architecture Brain Actions 12.81 introuvable."
}

if (-not $brain.Contains("KLYX_GROUP_ACTIONS_12_85")) {
    throw "12.91 : protection groupes 12.85 introuvable."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $routePath -Destination ($routePath + ".bak-12-91-" + $timestamp) -Force

if (Test-Path -LiteralPath $helperPath) {
    Copy-Item -LiteralPath $helperPath -Destination ($helperPath + ".bak-12-91-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($helperPath, $groupActions, $utf8)
[System.IO.File]::WriteAllText($routePath, $actionsRoute, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.91 APPLIQUE"
Write-Host "======================================"
Write-Host "Decision annulation Action Center : OK"
Write-Host "Attente demandeur : OK"
Write-Host "Remboursement en cours : OK"
Write-Host "Remboursement echoue prioritaire : OK"
Write-Host "Actions concurrentes groupe : MASQUEES"
Write-Host "Execution automatique : NON"
Write-Host "======================================"
